323	// int64-nanosecond range still align to coarse multiples of the epoch and
324	// do not spill into a neighboring coarse window through overflow.
325	func TestRollupExtremeTimestamps(t *testing.T) {
326		const fine = 10 * time.Second
327		for _, at := range []time.Time{
328			time.Unix(1<<62, 123456789),
329			time.Unix(-1<<62, 987654321),
330			time.Unix(0, math.MaxInt64),
