335				t.Fatal(err)
336			}
337			fineStart := wantStart(at, fine)
338			v := r.Rollup(4) // 40s coarse windows
339			want := wantStart(fineStart, 40*time.Second)
340			w := v.Window(want)
341			if w.Count != 1 || w.Sum != 3 || w.Min != 3 || w.Max != 3 {
342				t.Fatalf("at %v: coarse window at %v: %+v", at, want, w)
343			}
344			if !w.Start.Equal(want) {
345				t.Fatalf("at %v: coarse start %v, want %v", at, w.Start, want)
346			}
347			// The aligned fine start itself is never a coarse boundary here
348			// unless it is a multiple of the coarse size.
349			if !fineStart.Equal(want) {
350				if w := v.Window(fineStart); w.Count != 0 {
351					t.Fatalf("at %v: fine start %v is not a coarse start", at, fineStart)
352				}
