357	// TestRollupConcurrentWithWrites derives views while batches are filed
358	// continuously: every derived coarse window must be epoch aligned and
359	// internally consistent, and a batch must appear whole or not at all.
360	// Run with -race to catch data races.
361	func TestRollupConcurrentWithWrites(t *testing.T) {
362		r := New(time.Millisecond)
363		var writers sync.WaitGroup
364		stop := make(chan struct{})
365		for g := 0; g < 4; g++ {
366			writers.Add(1)
367			go func(g int) {
368				defer writers.Done()
369				at := time.Unix(0, 0)
370				for {
371					select {
372					case <-stop:
373						return
374					default:
375					}
376					_ = r.AddBatch([]Sample{
377						{At: at, Value: float64(g)},
378						{At: at.Add(time.Millisecond), Value: float64(g)},
379					})
380					at = at.Add(2 * time.Millisecond)
381				}
382			}(g)
383		}
384		for i := 0; i < 200; i++ {
