394					t.Fatalf("misaligned coarse window: %+v", w)
395				}
396				if w.Count <= 0 || w.Min > w.Max {
397					t.Fatalf("torn coarse window: %+v", w)
398				}
399			}
400			// A cursor over the same frozen view must hand out each window once.
401			c := v.Cursor(time.Unix(-1, 0), time.Unix(1<<30, 0))
