func TestRunShortestFloatFormatting(t *testing.T) {
	// 1e20 renders "1e+20" under 'g' -1, and a sum that loses the small
	// addend shows that values pass through unchanged.
	content := "0 1e20\n0 150000\n"
	got := runWithFile(t, content, "--window", "1m", "windows")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	fields := strings.Fields(got.stdout)
	if len(fields) != 5 {
		t.Fatalf("stdout = %q", got.stdout)
	}
	if fields[2] != "1.0000000000000002e+20" && fields[2] != "1e+20" {
		t.Fatalf("sum format = %q", fields[2])
	}
	if fields[3] != "150000" || fields[4] != "1e+20" {
		t.Fatalf("min/max format = %q %q", fields[3], fields[4])
	}
}

